import openpyxl
from openpyxl.styles import Font

# Load the workbook and select the sheet
wb = openpyxl.load_workbook('/tmp/sb_g42wr5ll/input.xlsx')
ws = wb['Sheet1']

# Set '等线' font for the entire sheet
eq_font = Font(name='等线')
for row in ws.iter_rows():
    for cell in row:
        cell.font = eq_font

# Process rows 7 to 23, columns N (14) and O (15)
for row in range(7, 24):
    n_cell = ws.cell(row=row, column=14)  # Column N
    o_cell = ws.cell(row=row, column=15)  # Column O

    n_val = n_cell.value
    if isinstance(n_val, (int, float)):
        if n_val > 40:
            n_cell.value = 40
            o_cell.value = n_val - 40
        else:
            # Keep N unchanged, set overtime to 0
            o_cell.value = 0

# Apply number formatting to N7:O23
# Use #,##0.## for non-whole numbers, General for whole numbers
for row in range(7, 24):
    for col in (14, 15):
        cell = ws.cell(row=row, column=col)
        val = cell.value
        if isinstance(val, (int, float)):
            if val == int(val):
                cell.number_format = 'General'
            else:
                cell.number_format = '#,##0.##'
        else:
            cell.number_format = 'General'

# Save the modified workbook
wb.save('/tmp/sb_g42wr5ll/output.xlsx')
